const form=document.getElementById('join-form');let message='';document.querySelectorAll('[data-interest]').forEach(b=>b.addEventListener('click',()=>{document.getElementById('interest').value=b.dataset.interest;document.getElementById('join').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.getElementById('thought').focus({preventScroll:true})}));form.addEventListener('submit',e=>{e.preventDefault();const name=document.getElementById('name').value.trim()||'名前は未記入';message=`We are Oneness｜UFOセンター構想への参加メッセージ\n\nお名前：${name}\n関わり方：${document.getElementById('interest').value}\n\n${document.getElementById('thought').value.trim()}\n\n※これは作成したメッセージです。参加登録・主催者への送信はされていません。`;document.getElementById('preview').textContent=message;document.getElementById('result').hidden=false;document.getElementById('copy-status').textContent='メッセージを作成しました。保存してお手元に残せます。';document.getElementById('result').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'})});document.getElementById('copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(message);document.getElementById('copy-status').textContent='コピーしました。'}catch{document.getElementById('copy-status').textContent='コピーできませんでした。本文を選択してコピーするか、テキストで保存してください。'}});document.getElementById('download').addEventListener('click',()=>{const blob=new Blob(['\uFEFF'+message],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='oneness-参加メッセージ.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);document.getElementById('copy-status').textContent='テキストファイルの保存を開始しました。'});
